(function(){"use strict";
const API="/api",TOKEN="cs360_portal_colaborador_token",services=window.CS360RequestForm.services;
let profile=null,currentService=null,currentJourney=null;
const $=id=>document.getElementById(id),esc=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
async function api(path,options={}){const response=await fetch(API+path,{...options,headers:{"Content-Type":"application/json",...(localStorage.getItem(TOKEN)?{Authorization:`Bearer ${localStorage.getItem(TOKEN)}`}:{})}}),body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error?.message||"Não foi possível concluir a operação.");return body}
async function authenticate(){let token=localStorage.getItem(TOKEN);if(!token){const login=await api("/auth/login",{method:"POST",body:JSON.stringify({email:"carlos.andrade@ficticio.org"})});token=login.data.token;localStorage.setItem(TOKEN,token)}try{profile=(await api("/auth/employee-profile")).data}catch{localStorage.removeItem(TOKEN);const login=await api("/auth/login",{method:"POST",body:JSON.stringify({email:"carlos.andrade@ficticio.org"})});localStorage.setItem(TOKEN,login.data.token);profile=(await api("/auth/employee-profile")).data}}
function renderCatalog(){$("request-catalog").innerHTML=Object.entries(services).map(([id,service])=>service.disabled?`<article class="request-service disabled" aria-disabled="true"><strong>${service.name}</strong><span>${service.description}</span><small>EM LEVANTAMENTO</small><b>Indisponível no protótipo</b></article>`:`<button class="request-service" type="button" data-service="${id}"><strong>${service.name}</strong><span>${service.description}</span><b>Solicitar →</b></button>`).join("");document.querySelectorAll("[data-service]").forEach(button=>button.onclick=()=>selectService(button.dataset.service))}
function corporateData(){const values=[["Nome",profile.nome],["Área",profile.departamento],["Centro de custo",profile.centroCusto],["Gestor",profile.gestor]];$("corporate-grid").innerHTML=values.map(([label,value])=>`<div><small>${label}</small><strong>${esc(value)}</strong><span>🔒</span></div>`).join("")}
function fieldHtml(field){const [name,label,type,required,options]=field,attrs=`name="${name}" id="field-${name}" ${required?"required":""}`;if(type==="textarea")return `<div class="field full"><label for="field-${name}">${label}${required?" *":""}</label><textarea ${attrs} rows="3"></textarea></div>`;if(type==="select")return `<div class="field"><label for="field-${name}">${label}${required?" *":""}</label><select ${attrs}><option value="">Selecione</option>${options.map(option=>`<option value="${esc(option)}">${esc(option)}</option>`).join("")}</select></div>`;return `<div class="field"><label for="field-${name}">${label}${required?" *":""}</label><input type="${type}" ${attrs}></div>`}
function renderFields(){const service=services[currentService];$("dynamic-fields").innerHTML=service.fields.map(fieldHtml).join("");$("dynamic-fields").hidden=false;$("submit-request").disabled=false}
function renderJourneys(){const service=services[currentService];$("journey-choice").hidden=false;$("journey-choice").innerHTML=`<h3>O que você precisa?</h3><div class="journey-buttons">${Object.entries(service.journeys).map(([id,label])=>`<button type="button" data-journey="${id}">${label}<span>→</span></button>`).join("")}</div>`;$("dynamic-fields").hidden=true;$("submit-request").disabled=true;document.querySelectorAll("[data-journey]").forEach(button=>button.onclick=()=>{currentJourney=button.dataset.journey;document.querySelectorAll("[data-journey]").forEach(item=>item.classList.toggle("selected",item===button));renderFields();setAssistant()})}
function selectService(id,journey=null){const service=services[id];if(!service||service.disabled)return;currentService=id;currentJourney=journey;$("service-step").hidden=true;$("form-step").hidden=false;$("confirmation-step").hidden=true;$("form-title").textContent=`Nova Solicitação › ${service.name}`;$("form-description").textContent=service.description;corporateData();$("journey-choice").hidden=true;if(service.journeys&&!journey)renderJourneys();else renderFields();setAssistant();history.replaceState(null,"",`?service=${encodeURIComponent(id)}${journey?`&journey=${encodeURIComponent(journey)}`:""}`);scrollTo({top:0,behavior:"smooth"})}
function setAssistant(){const service=currentService?services[currentService]:null,assistant=$("assistant");assistant.dataset.role="COLABORADOR";assistant.dataset.currentPage="portal-colaborador-nova-solicitacao";assistant.dataset.currentService=currentService||"";$("assistant-context").textContent=service?`Nova Solicitação · ${service.name}`:"Nova Solicitação"}
function showError(message){let error=document.querySelector(".request-error");if(!error){error=document.createElement("div");error.className="request-error";$("portal-request-form").prepend(error)}error.textContent=message;error.scrollIntoView({behavior:"smooth",block:"center"})}
$("portal-request-form").onsubmit=async event=>{event.preventDefault();if(!currentService||services[currentService].disabled)return;const submit=$("submit-request");submit.disabled=true;submit.textContent="Enviando…";try{const details=window.CS360RequestForm.collect(event.currentTarget);if(currentJourney){details.journey=currentJourney;details.accessType=currentJourney==="PERDA_ACESSO"?"Comunicar perda de acesso":"Solicitar acesso especial"}details.employeeFieldsSource="EmployeeProfile";const created=await api("/requests",{method:"POST",body:JSON.stringify({serviceType:currentService,title:$("request-title").value.trim(),requesterId:profile.employeeId,requesterName:profile.nome,costCenter:profile.centroCusto,details,urgent:false})});const submitted=await api(`/requests/${encodeURIComponent(created.data.id)}/submit`,{method:"PUT",body:"{}"});$("form-step").hidden=true;$("confirmation-step").hidden=false;$("confirmation-id").textContent=submitted.data.id;$("confirmation-status").textContent="Aguardando aprovação";$("confirmation-copy").textContent=`Seu pedido de ${services[currentService].name} foi registrado e já pode ser acompanhado.`;$("view-request").href=`portal-colaborador.html?view=requests&request=${encodeURIComponent(submitted.data.id)}`;history.replaceState(null,"",`?confirmation=${encodeURIComponent(submitted.data.id)}`);scrollTo({top:0,behavior:"smooth"})}catch(error){showError(error.message);submit.disabled=false;submit.textContent="Enviar solicitação"}};
$("change-service").onclick=()=>{currentService=null;currentJourney=null;$("form-step").hidden=true;$("service-step").hidden=false;history.replaceState(null,"","portal-colaborador-nova-solicitacao.html");setAssistant();scrollTo({top:0,behavior:"smooth"})};$("assistant-open").onclick=()=>{$("assistant").hidden=false;setAssistant()};$("assistant-close").onclick=()=>$("assistant").hidden=true;$("theme").onclick=()=>{const theme=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=theme;localStorage.setItem("cs360_theme",theme)};document.onkeydown=event=>{if(event.key==="Escape")$("assistant").hidden=true};
async function init(){document.documentElement.dataset.theme=localStorage.getItem("cs360_theme")||"dark";renderCatalog();setAssistant();try{await authenticate();const params=new URLSearchParams(location.search),service=params.get("service"),journey=params.get("journey");if(service)selectService(service,journey)}catch(error){showError("API demonstrativa indisponível. Tente novamente em instantes.")}}
init();
})();
